examples.good:
const REFUND_ELIGIBILITY_THRESHOLD_CENTS = 100;
const EMBEDDING_BATCH_SIZE = 128;
const REFUND_WINDOW_MS = 24 * 60 * 60 * 1000;

if (order.totalCents > REFUND_ELIGIBILITY_THRESHOLD_CENTS) {
  this.logger.log('eligible for refund');
}

for (let i = 0; i < EMBEDDING_BATCH_SIZE; i++) {
  await this.processChunk(items[i]);
}

if (Date.now() - order.createdAt.getTime() > REFUND_WINDOW_MS) {
  throw new BadRequestException('refund window expired');
}

